#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Pilot setup for PawPin: the stages below are specific to this repository.
#
# What this wizard does and does not do:
#   - It guides you through the pages and commands only the owner can use (Apple, Supabase, Sentry,
#     EAS) and remembers the values you type in .env.pilot (git-ignored, mode 0600).
#   - It shows every command and asks before it runs it. Nothing runs unattended, and it is safe to
#     answer "n" to any of them and run the command yourself.
#   - It never asks for a password, the Supabase service-role key or a token. Those go straight
#     from the dashboard to the place that needs them (a Supabase SQL box, or EAS's own prompt).
#   - Run it from anywhere inside the repository: it changes to the repository root first.

# Remembered answers. The name starts with ".env", so .gitignore keeps it out of the repository.
PILOT_ENV_FILE=".env.pilot"

RAN_OK=0       # offer_run sets it to 1 when the command ran and succeeded
# eas-cli names this command env:set; a much older one calls it env:create (EAS_ENV_VERB=env:create).
EAS_ENV_VERB="${EAS_ENV_VERB:-env:set}"
EAS_ARGS=()

# _cmdline ARGS...: the command as one copy-pasteable line.
_cmdline() {
  local out="" a sq="'\\''"
  for a in "$@"; do
    if [[ "$a" =~ ^[A-Za-z0-9_@%+=:,./-]+$ ]]; then
      out+="$a "
    else
      out+="'${a//\'/$sq}' "
    fi
  done
  printf '%s' "${out% }"
}

_show_cmd() {
  if [[ "$1" == "." ]]; then
    printf '    %s$ %s%s\n' "$BOLD" "$2" "$RESET"
  else
    printf '    %s$ (cd %s && %s)%s\n' "$BOLD" "$1" "$2" "$RESET"
  fi
}

# offer_run DIR "what it does" CMD ARGS...
# Shows the command, and runs it in DIR only if the human says yes. A "no" is not an error: the
# command is listed in the closing summary so it can be run by hand. Always returns success; read
# RAN_OK to know whether it ran.
offer_run() {
  local dir="$1" why="$2" line rc=0
  shift 2
  line="$(_cmdline "$@")"
  RAN_OK=0
  printf '\n'
  say "$why"
  _show_cmd "$dir" "$line"
  if ! confirm "Run it now?"; then
    SKIPPED+=("not run yet, from ${dir}: ${line}")
    note "Not run. It is listed in the summary at the end."
    return 0
  fi
  ( cd "$dir" && "$@" ) || rc=$?
  if (( rc != 0 )); then
    warn "That exited with status $rc. Read the message above, fix the cause, and run the same command by hand."
    SKIPPED+=("failed, run again from ${dir}: ${line}")
  else
    RAN_OK=1
    printf '  %s✓ done%s\n' "$GREEN" "$RESET"
  fi
  return 0
}

# ask_match KEY "Prompt" 'regex' "what a valid value looks like": asks until the answer matches.
ask_match() {
  local key="$1" prompt="$2" re="$3" hint="$4"
  while :; do
    ask "$key" "$prompt" || return 1
    if [[ "${!key}" =~ $re ]]; then return 0; fi
    warn "That does not look right: $hint"
  done
}

# show_block "text" prints text indented, to be read or pasted.
show_block() {
  local line
  while IFS= read -r line; do
    printf '    %s%s%s\n' "$BOLD" "$line" "$RESET"
  done <<<"$1"
}

# offer_copy "text": copies it to the clipboard if the human wants and a clipboard tool exists.
offer_copy() {
  local tool=""
  if command -v pbcopy >/dev/null 2>&1; then tool="pbcopy"
  elif command -v wl-copy >/dev/null 2>&1; then tool="wl-copy"
  elif command -v xclip >/dev/null 2>&1; then tool="xclip -selection clipboard"
  elif command -v clip.exe >/dev/null 2>&1; then tool="clip.exe"
  fi
  [[ -n "$tool" ]] || return 0
  if confirm "Copy it to your clipboard?"; then
    # shellcheck disable=SC2086  # $tool is one of the fixed commands above.
    if printf '%s' "$1" | $tool; then
      printf '  %s✓ copied%s\n' "$GREEN" "$RESET"
    else
      warn "Could not copy it: select and copy the text above."
    fi
  fi
}

# A key that ships inside the app must be the public one. 0: public. 1: a secret key (refuse).
# 2: could not tell.
check_public_key() {
  local key="$1" payload json
  case "$key" in
    sb_publishable_*) return 0 ;;
    sb_secret_*) return 1 ;;
    eyJ*.*.*)
      payload="${key#*.}"
      payload="${payload%%.*}"
      payload="${payload//-/+}"
      payload="${payload//_//}"
      while (( ${#payload} % 4 != 0 )); do payload+="="; done
      json="$({ printf '%s' "$payload" | base64 -d 2>/dev/null || printf '%s' "$payload" | base64 -D 2>/dev/null; } || true)"
      case "$json" in
        *'"role":"service_role"'*) return 1 ;;
        *'"role":"anon"'*) return 0 ;;
      esac
      return 2 ;;
  esac
  return 2
}

# A date about five months ahead: when to regenerate Apple's sign-in secret (it lasts six).
reminder_date() {
  date -v+5m +%Y-%m-%d 2>/dev/null || date -d '+5 months' +%Y-%m-%d 2>/dev/null || echo "five months from today"
}

# _eas_env_args NAME VALUE VISIBILITY fills EAS_ARGS with one `eas env:set` command.
_eas_env_args() {
  EAS_ARGS=(eas "$EAS_ENV_VERB" --name "$1" --value "$2" --environment production --environment preview \
    --visibility "$3" --non-interactive)
  if [[ "$EAS_ENV_VERB" == "env:create" ]]; then EAS_ARGS+=(--force); fi
  return 0
}

run_wizard() {

TOTAL_STAGES=20

# Everything is relative to the repository root, wherever the script is started from.
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
ENV_FILE="$PILOT_ENV_FILE"

banner "PawPin pilot setup: Apple, Supabase, Sentry, EAS"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up the hosted pilot: iOS builds for TestFlight, the web app, and the Supabase backend."
say "It never runs a command without showing it and asking. It never asks for a password,"
say "the service-role key or a token."
note "Answers are remembered in $ENV_FILE (git-ignored), so you can stop and run it again."
note "Dashboards move their menus around. If a page is not where it is described, use its search."
printf '\n'
say "You will need:"
step "An Apple Developer account (US\$99 a year)"
step "A Supabase organisation on the Pro plan (about US\$25 a month; budget target US\$200 a month)"
step "An Expo account (the free tier is enough) and a Sentry account (free tier is enough)"
step "An SMTP service for sign-in emails: Supabase's own sender only mails your own team"
step "A shared support mailbox, not a personal one, if you want an 'ask for an invite' link"
printf '\n'
say "Tools on this machine:"
for tool in node pnpm git curl eas; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '    %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    printf '    %s✗%s %s (missing)\n' "$YELLOW" "$RESET" "$tool"
  fi
done
if command -v node >/dev/null 2>&1; then
  node_major="$(node -p 'process.versions.node.split(".")[0]')"
  (( node_major >= 24 )) || warn "Node $node_major found; this repository needs Node 24 (package.json engines)."
fi
if ! command -v pnpm >/dev/null 2>&1; then
  warn "pnpm 11 is required (see https://pnpm.io/installation). Install it, then run this again."
  exit 1
fi
if [[ ! -d node_modules ]]; then
  offer_run . "Dependencies are not installed here." pnpm install --frozen-lockfile
fi
if ! command -v eas >/dev/null 2>&1 && command -v npm >/dev/null 2>&1; then
  offer_run . "The EAS command line is not installed (the build and deploy scripts call it)." npm install -g eas-cli
fi
printf '\n'
pause "Press Enter to begin."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Apple Developer Program"
say "Sign in with Apple, TestFlight and the App Store all need a paid Apple Developer account."
open_url "https://developer.apple.com/programs/enroll/"
step "Enrol (individual or organisation, US\$99 a year). Approval can take a day or two."
step "Wait until you can sign in at developer.apple.com/account with the Membership showing."
pause "Enrolled and approved? Press Enter."
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Under 'Membership details', find the Team ID (10 letters and digits)."
ask_match APPLE_TEAM_ID "Team ID:" '^[A-Z0-9]{10}$' "10 capital letters and digits, like AB12CD34EF"
write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Bundle id and App ID"
BUNDLE_ID="$(sed -n "s/.*bundleIdentifier: '\([^']*\)'.*/\1/p" apps/app/app.config.ts | head -n1)"
if [[ -z "$BUNDLE_ID" ]]; then
  warn "Could not read ios.bundleIdentifier from apps/app/app.config.ts."
  ask_match BUNDLE_ID "Bundle id:" '^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$' "reverse-DNS, like com.pawpin.pilot"
fi
say "The app's iOS bundle id is  $BOLD$BUNDLE_ID$RESET  (apps/app/app.config.ts)."
note "It cannot be changed once the app is in App Store Connect, so decide now."
if confirm "Use a different bundle id?"; then
  old_id="$BUNDLE_ID"
  ask_match BUNDLE_ID "New bundle id:" '^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$' "reverse-DNS, like com.yourname.pawpin"
  if [[ "$BUNDLE_ID" != "$old_id" ]]; then
    say "I will replace $old_id with $BUNDLE_ID in these files:"
    changed_files=()
    for f in apps/app/app.config.ts apps/app/e2e/maestro/registry-happy-path.yaml apps/app/src/config.test.ts README.md; do
      if [[ -f "$f" ]] && grep -qF "$old_id" "$f"; then
        changed_files+=("$f"); step "$f"
      fi
    done
    if (( ${#changed_files[@]} == 0 )); then
      warn "None of the files mention $old_id, so nothing to change."
      BUNDLE_ID="$old_id"
    elif confirm "Edit them now?"; then
      old_pattern="${old_id//./\\.}"
      for f in "${changed_files[@]}"; do
        sed -i.bak "s/${old_pattern}/${BUNDLE_ID}/g" "$f" && rm -f "$f.bak"
      done
      printf '  %s✓ edited%s %s\n' "$GREEN" "$RESET" "${changed_files[*]}"
      note "Review with git diff and commit. If apps/app/ios exists, run expo prebuild --clean there later."
    else
      BUNDLE_ID="$old_id"
      SKIPPED+=("bundle id change to the new id was not applied; the app still uses $old_id")
    fi
  fi
fi
printf '\n'
say "Register it as an App ID, with Sign in with Apple switched on:"
open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
step "Choose 'App IDs', then 'App', then Continue."
step "Description: PawPin.  Bundle ID: Explicit, $BUNDLE_ID"
step "Under Capabilities tick 'Sign in with Apple', then Continue and Register."
pause "App ID registered? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect app record"
say "TestFlight needs an app record that uses the bundle id above."
open_url "https://appstoreconnect.apple.com/apps"
step "Click the + button, then 'New App'."
step "Platforms: iOS.  Name: PawPin (the name must be free in the App Store; choose another if not)."
step "Primary language: your choice.  Bundle ID: pick $BUNDLE_ID from the list."
step "SKU: any unique text, for example pawpin-pilot.  User access: Full Access.  Create."
pause "App record created? Press Enter."
note "EAS Submit asks for the app's numeric Apple ID later if it needs it (App Information)."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase project"
say "One hosted project holds the pilot: database, sign-in, photo storage and the two functions."
open_url "https://supabase.com/dashboard/new"
step "Pick your organisation (on the Pro plan), name the project pawpin-pilot."
step "Set a strong database password and keep it in your password manager. The wizard never asks for it."
step "Pick the region closest to your testers, then Create new project and wait for it to be ready."
pause "Project ready? Press Enter."
step "Project Settings → General: copy the Reference ID (20 lowercase letters)."
ask_match SUPABASE_PROJECT_REF "Reference ID:" '^[a-z]{20}$' "20 lowercase letters, like abcdefghijklmnopqrst"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env EXPO_PUBLIC_SUPABASE_URL "https://${SUPABASE_PROJECT_REF}.supabase.co"
DASH="https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}"
printf '\n'
open_url "$DASH/settings/api-keys"
step "Open API Keys and use the Legacy tab if the page has one."
step "Copy the anon (public) key: a long text starting eyJ. The publishable key (sb_publishable_) also works."
warn "Never the service_role or secret key: this one is put inside the app that everyone downloads."
while :; do
  ask_secret EXPO_PUBLIC_SUPABASE_ANON_KEY "Anon (public) key (hidden as you paste):"
  rc=0; check_public_key "$EXPO_PUBLIC_SUPABASE_ANON_KEY" || rc=$?
  if (( rc == 0 )); then break; fi
  if (( rc == 1 )); then warn "That is a secret key. It must not go in the app. Copy the anon key instead."; continue; fi
  warn "I could not tell what kind of key that is."
  if confirm "It is the anon (public) key, not service_role. Use it?"; then break; fi
done
write_env EXPO_PUBLIC_SUPABASE_ANON_KEY "$EXPO_PUBLIC_SUPABASE_ANON_KEY"
offer_run . "Sign the Supabase command line in (it opens your browser)." pnpm exec supabase login
offer_run . "Link this folder to the hosted project (it asks for the database password)." \
  pnpm exec supabase link --project-ref "$SUPABASE_PROJECT_REF"
note "Do not use 'supabase config push': it would copy the local config.toml (with its raised"
note "sign-in limits and local-only settings) onto the hosted project."
pause "Press Enter to continue."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Spend cap and usage alerts (budget target US\$200 a month)"
say "Expected cost is about US\$25 a month for Supabase Pro, plus Apple's US\$99 a year."
say "The target ceiling is US\$200 a month, so decide this before anyone uses the project."
open_url "https://supabase.com/dashboard/organizations"
step "Choose your organisation, then Billing. Find 'Cost Control' and turn the Spend Cap ON."
step "With the cap on, usage stops at the plan's quota instead of being billed: no surprise invoice."
step "Open the organisation's Usage page and look for email alerts or usage notifications."
note "When this wizard was written, Supabase's docs described no threshold alert for spend."
note "If you cannot find one, set a weekly reminder to read Usage and 'Upcoming invoice'."
note "Alert at US\$200 (or earlier) if there is a setting. Turning the cap off is your call."
if confirm "Spend cap is ON and an alert or weekly reminder is in place?"; then
  note "Good."
else
  SKIPPED+=("Supabase: turn the Spend Cap on and set a usage alert or weekly check (target US\$200 a month)")
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy the database and the two functions"
say "This applies the migrations to the hosted project and deploys delete-account and"
say "storage-cleanup. Supabase asks you to confirm the migrations before it applies them."
offer_run . "Push the migrations and deploy the functions." pnpm db:push
printf '\n'
say "Check that the hosted functions honour verify_jwt = false (from supabase/config.toml)."
say "This asks delete-account who is calling, with no sign-in at all. It is harmless: it answers 401."
offer_run . "Call the function without a sign-in." \
  curl -sS -i -X POST "https://${SUPABASE_PROJECT_REF}.supabase.co/functions/v1/delete-account"
printf '\n'
say "Read the answer:"
step 'A body of  {"error":"PAWPIN:UNAUTHENTICATED"}  means the function itself answered: all good.'
step 'A gateway message such as "Missing authorization header" or "Invalid JWT" means the platform'
step "checked the JWT first. Re-deploy with:"
show_block "pnpm exec supabase functions deploy delete-account storage-cleanup --no-verify-jwt"
if confirm "Did you see PAWPIN:UNAUTHENTICATED?"; then
  note "verify_jwt = false is honoured."
else
  SKIPPED+=("confirm hosted verify_jwt=false: curl -i -X POST https://${SUPABASE_PROJECT_REF}.supabase.co/functions/v1/delete-account must return PAWPIN:UNAUTHENTICATED")
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Sign in with Apple (web and the project's provider)"
say "iOS signs in with an Apple identity token and needs only the bundle id. The web needs a"
say "Services ID, a key, and a secret generated from that key."
APPLE_SERVICE_ID_DEFAULT="${BUNDLE_ID}.web"
open_url "https://developer.apple.com/account/resources/identifiers/add/serviceId"
step "Services ID: Description PawPin Web, Identifier $APPLE_SERVICE_ID_DEFAULT (or your own). Register."
step "Open it, tick 'Sign in with Apple', then Configure:"
step "  Primary App ID: the one you made.  Domain: ${SUPABASE_PROJECT_REF}.supabase.co"
step "  Return URL: https://${SUPABASE_PROJECT_REF}.supabase.co/auth/v1/callback   then Save."
ask_match APPLE_SERVICE_ID "Services ID you used:" '^[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$' "reverse-DNS, like $APPLE_SERVICE_ID_DEFAULT"
write_env APPLE_SERVICE_ID "$APPLE_SERVICE_ID"
printf '\n'
open_url "https://developer.apple.com/account/resources/authkeys/add"
step "Key name: PawPin Sign in with Apple. Tick 'Sign in with Apple', Configure, choose the App ID."
step "Continue, Register, then Download the .p8 file. Apple lets you download it once: keep it safe."
step "The Key ID (10 characters) is on the key's page and in the file name AuthKey_XXXXXXXXXX.p8."
ask_match APPLE_KEY_ID "Key ID:" '^[A-Z0-9]{10}$' "10 capital letters and digits"
write_env APPLE_KEY_ID "$APPLE_KEY_ID"
printf '\n'
say "Now generate the client secret from the .p8 file with Supabase's generator."
open_url "https://supabase.com/docs/guides/auth/social-login/auth-apple"
step "Find 'Generate a client_secret'. Use Firefox or Chrome (not Safari). Enter Team ID $APPLE_TEAM_ID, Services ID $APPLE_SERVICE_ID,"
step "Key ID $APPLE_KEY_ID and the .p8 file. The key stays in your browser. Copy the secret it makes."
printf '\n'
open_url "$DASH/auth/providers"
step "Authentication → Sign In / Providers → Apple: switch Enable on."
step "Client IDs:  ${APPLE_SERVICE_ID},${BUNDLE_ID}  (Services ID first, then the bundle id)."
step "Secret Key: paste the generated secret. Save."
pause "Apple provider saved? Press Enter."
SECRET_REMINDER="$(reminder_date)"
warn "The generated secret expires after 6 months and web sign-in then fails. Remind yourself by $SECRET_REMINDER."
SKIPPED+=("regenerate the Apple sign-in secret from the .p8 and paste it into Supabase before $SECRET_REMINDER (it lasts 6 months)")
SKIPPED+=("pilot check: the native Apple id-token sign-in has never run end to end; try it on a TestFlight build")

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Auth hook: the invite-only allowlist"
say "Supabase Auth calls identity.before_user_created before it creates any user, and refuses"
say "anyone who is not in identity.pilot_allowlist. On a hosted project the hook is switched on here."
open_url "$DASH/auth/hooks"
step "Authentication → Hooks → 'Before User Created': add or enable the hook."
step "Type: Postgres function.  Schema: identity.  Function: before_user_created.  Save."
note "The migrations already granted it to supabase_auth_admin; do not rewrite the function."
note "Locally, a change to the hook in supabase/config.toml needs 'supabase stop && supabase start'."
pause "Hook enabled? Press Enter."
SKIPPED+=("pilot check: sign in with an address that is not on the allowlist; it must say 'This pilot is invite-only'")

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Vault secrets for the storage cleanup job"
say "Every 5 minutes the database calls the storage-cleanup function. It reads two Vault secrets:"
say "project_url and service_role_key. The key must be exactly the one the function sees as"
say "SUPABASE_SERVICE_ROLE_KEY: the project's service_role key."
open_url "$DASH/sql/new"
step "Open the SQL Editor and run the first line as it is:"
VAULT_URL_SQL="select vault.create_secret('https://${SUPABASE_PROJECT_REF}.supabase.co', 'project_url');"
show_block "$VAULT_URL_SQL"
offer_copy "$VAULT_URL_SQL"
printf '\n'
open_url "$DASH/settings/api-keys"
step "On API Keys (Legacy tab) reveal the service_role key and copy it. Do not paste it anywhere else."
step "In the SQL Editor run this, with the key between the quotes:"
show_block "select vault.create_secret('<paste the service_role key here>', 'service_role_key');"
note "Running this stage again? create_secret fails when the name already exists (names are unique)."
note "To change a value, use update_secret instead, once per secret (project_url or service_role_key):"
show_block "select vault.update_secret(id, 'the new value') from vault.secrets where name = 'service_role_key';"
pause "Both secrets created? Press Enter."
say "After the next 5-minute tick, check the job got through (status_code 200, not 401):"
show_block "select status_code, left(content, 100) as content, created from net._http_response order by created desc limit 5;"
SKIPPED+=("pilot check: in the SQL Editor, net._http_response must show status_code 200 for storage-cleanup (401 means the Vault service_role_key does not match)")

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Data API: expose only api, and switch off pg_graphql"
say "Only the api schema is meant to be reachable by the app. pg_graphql would add a second way in."
open_url "$DASH/settings/api"
step "Project Settings → API (or Integrations → Data API → Settings): 'Exposed schemas'."
step "It must list only:  api   Remove public and graphql_public if they are there. Save."
printf '\n'
open_url "$DASH/database/extensions"
step "Database → Extensions: search pg_graphql and switch it off (disable)."
say "Or in the SQL Editor:"
show_block "drop extension if exists pg_graphql;"
say "Check, in the SQL Editor (should return no rows):"
show_block "select extname from pg_extension where extname = 'pg_graphql';"
pause "Both done? Press Enter."

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Sign-in emails: your SMTP, the 6-digit code, the template"
say "Supabase's built-in sender only emails members of your own organisation, 2 an hour."
say "Testers need your own SMTP service."
open_url "$DASH/auth/smtp"
step "Authentication → Emails → SMTP Settings: switch on custom SMTP and fill in your provider's"
step "host, port, user, password and sender address. Save."
note "Supabase then allows 30 emails an hour. Leave the hosted rate limits at their defaults."
printf '\n'
open_url "$DASH/auth/providers"
step "Authentication → Sign In / Providers → Email: Email OTP length 6, expiration 600 seconds."
note "The email says the code lasts 10 minutes, which is 600 seconds. If the length field is not"
note "shown the default of 6 applies."
printf '\n'
open_url "$DASH/auth/templates"
step "Authentication → Emails → Templates. Edit BOTH 'Confirm sign up' and 'Magic link'."
step "Subject: Your PawPin sign-in code"
step "Body: the contents of supabase/templates/sign-in-code.html (it uses the 6-digit {{ .Token }})."
if [[ -f supabase/templates/sign-in-code.html ]]; then
  offer_copy "$(cat supabase/templates/sign-in-code.html)"
fi
pause "Both templates saved? Press Enter."
SKIPPED+=("note: hosted Auth allows one email per address per 60 seconds by default, but the app offers Resend after 30; an early Resend shows 'Take a short break'")

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Support address for the invite-only message"
say "People who are not invited see 'This pilot is invite-only'. With a support address set, the"
say "message also links to it so they can ask for an invite. With none, there is no link."
warn "The address ends up in the app and in the web page source, so everyone can read it."
say "Use a shared mailbox such as help@yourdomain, not a personal one. Leave it empty for no link."
note "Type - to clear an address saved earlier."
while :; do
  ask EXPO_PUBLIC_SUPPORT_EMAIL "Support address (or empty):" || true
  address="${EXPO_PUBLIC_SUPPORT_EMAIL:-}"
  if [[ "$address" == "-" ]]; then EXPO_PUBLIC_SUPPORT_EMAIL=""; address=""; fi
  if [[ -z "$address" ]]; then break; fi
  if [[ ! "$address" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then
    warn "That is not an email address."; continue
  fi
  case "$address" in
    *@gmail.com|*@googlemail.com|*@icloud.com|*@me.com|*@outlook.com|*@hotmail.com|*@live.com|*@yahoo.com|*@proton.me|*@protonmail.com)
      warn "That looks like a personal mailbox."
      confirm "Publish it in the app anyway?" || continue ;;
  esac
  break
done
write_env EXPO_PUBLIC_SUPPORT_EMAIL "${EXPO_PUBLIC_SUPPORT_EMAIL:-}"

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Sentry project"
say "Errors are reported to Sentry with names, emails and file paths removed."
open_url "https://sentry.io/signup/"
step "Sign in (or sign up) and create or choose an organisation."
step "Projects → Create Project: platform React Native, name pawpin. Create."
step "Copy the DSN from the setup page, or Settings → Projects → pawpin → Client Keys (DSN)."
while :; do
  ask EXPO_PUBLIC_SENTRY_DSN "DSN (or empty to skip Sentry for now):" || true
  dsn="${EXPO_PUBLIC_SENTRY_DSN:-}"
  if [[ -z "$dsn" || "$dsn" =~ ^https://[A-Za-z0-9]+@[A-Za-z0-9.-]+/[0-9]+$ ]]; then break; fi
  warn "A DSN looks like https://<key>@o123.ingest.sentry.io/456"
done
write_env EXPO_PUBLIC_SENTRY_DSN "${EXPO_PUBLIC_SENTRY_DSN:-}"
if [[ -n "${EXPO_PUBLIC_SENTRY_DSN:-}" ]]; then
  printf '\n'
  say "Uploading source maps from iOS builds needs a token, the organisation slug and the project slug."
  say "Without a token the builds still pass; they just skip the upload."
  step "Organisation slug: Settings → General Settings → Organization Slug."
  ask_match SENTRY_ORG "Organisation slug:" '^[a-z0-9][a-z0-9-]*$' "lowercase letters, digits and dashes"
  step "Project slug: Settings → Projects → pawpin (the slug is in the address)."
  ask_match SENTRY_PROJECT "Project slug:" '^[a-z0-9][a-z0-9-]*$' "lowercase letters, digits and dashes"
  write_env SENTRY_ORG "$SENTRY_ORG"
  write_env SENTRY_PROJECT "$SENTRY_PROJECT"
  open_url "https://sentry.io/settings/account/api/auth-tokens/"
  step "Settings → Developer Settings → Organization Tokens → Create New Token. Copy it once."
  note "Do not paste the token here. EAS asks for it itself in the next-but-one stage."
fi
pause "Press Enter to continue."

# ── 15 ────────────────────────────────────────────────────────────────────
stage "EAS account, project and environment variables"
say "EAS builds the iOS app and hosts the web app. The values below are public ones, except the"
say "Sentry token, which EAS keeps as a secret. 'development' gets none: E2E uses the local stack."
offer_run . "Check whether you are already logged in to EAS." eas whoami
if (( RAN_OK == 0 )); then
  offer_run . "Log in to EAS (an interactive login in your terminal)." eas login
fi
offer_run apps/app "Create or link the EAS project for this app." eas init
printf '\n'
say "EAS builds and deploys need the project id inside apps/app/app.config.ts."
if ! grep -qE "projectId[[:space:]]*:" apps/app/app.config.ts; then
  warn "apps/app/app.config.ts has no projectId yet."
  say "'eas init' cannot edit a dynamic config, so add this inside the config object, and commit it"
  say "(a project id is not a secret):"
  show_block "extra: { eas: { projectId: '<the id eas init printed>' } },"
  note "If the Expo account is an organisation, also add  owner: '<organisation name>'."
fi
pause "Project linked, and projectId added if it was missing? Press Enter."
if ! grep -qE "projectId[[:space:]]*:" apps/app/app.config.ts; then
  warn "Still no projectId in apps/app/app.config.ts: EAS builds and deploys will fail until it is there."
  SKIPPED+=("add extra.eas.projectId (from eas init) to apps/app/app.config.ts and commit it")
fi

env_names=(EXPO_PUBLIC_SUPABASE_URL EXPO_PUBLIC_SUPABASE_ANON_KEY)
env_values=("$EXPO_PUBLIC_SUPABASE_URL" "$EXPO_PUBLIC_SUPABASE_ANON_KEY")
if [[ -n "${EXPO_PUBLIC_SUPPORT_EMAIL:-}" ]]; then
  env_names+=(EXPO_PUBLIC_SUPPORT_EMAIL); env_values+=("$EXPO_PUBLIC_SUPPORT_EMAIL")
fi
if [[ -n "${EXPO_PUBLIC_SENTRY_DSN:-}" ]]; then
  env_names+=(EXPO_PUBLIC_SENTRY_DSN SENTRY_ORG SENTRY_PROJECT)
  env_values+=("$EXPO_PUBLIC_SENTRY_DSN" "$SENTRY_ORG" "$SENTRY_PROJECT")
fi
say "These set the EAS variables for the production and preview environments. You are asked"
say "about each command in turn."
for i in "${!env_names[@]}"; do
  _eas_env_args "${env_names[$i]}" "${env_values[$i]}" plaintext
  offer_run apps/app "Set ${env_names[$i]} (a public value, stored as plaintext)." "${EAS_ARGS[@]}"
done
if [[ -n "${EXPO_PUBLIC_SENTRY_DSN:-}" ]]; then
  offer_run apps/app "Set the Sentry auth token as a secret. EAS asks you for the value; paste the token there." \
    eas "$EAS_ENV_VERB" --name SENTRY_AUTH_TOKEN --environment production --environment preview --visibility secret
fi
pause "Press Enter to continue."

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Deploy the web app"
say "Three steps, so nothing is published before it has been checked:"
step "1. Export the web app with the EAS production variables (stays on this machine)."
step "2. Check the export: it must not point at the local Supabase or carry the test seams."
step "3. Only if the check passes, upload it to EAS Hosting."
note "(The root 'pnpm deploy:web' script does 1 and 3 in one go, with no check in between.)"
printf '\n'
e2e_where=""
if [[ "${EXPO_PUBLIC_E2E:-}" == "1" ]]; then e2e_where="your shell"; fi
for f in apps/app/.env apps/app/.env.local apps/app/.env.production apps/app/.env.production.local; do
  if [[ -f "$f" ]] && grep -qE "^[[:space:]]*(export[[:space:]]+)?EXPO_PUBLIC_E2E=[\"']?1" "$f"; then e2e_where="$f"; fi
done
if [[ -n "$e2e_where" ]]; then
  warn "EXPO_PUBLIC_E2E=1 is set in $e2e_where. It would put the test-photo button in the hosted app."
  warn "Nothing was exported or deployed. Remove it, then run this wizard again (answers are kept)."
  SKIPPED+=("remove EXPO_PUBLIC_E2E=1 from $e2e_where, then run the wizard again: the web app was not deployed, and the stages after this one were not shown")
  pause "Press Enter to see what is still to do."
  finish
  return 0
fi
note "apps/app/.env holds your local values; the EAS production variables win for this command."
offer_run apps/app "1. Export the web app with the EAS production variables." \
  eas env:exec production "pnpm exec expo export --platform web"
deploy_ok=0
if (( RAN_OK == 1 )); then
  say "2. Checking the export (files on this machine only; nothing is sent):"
  problems=0
  if grep -rqF -e "127.0.0.1:54321" -e "localhost:54321" apps/app/dist 2>/dev/null; then
    warn "The export points at the LOCAL Supabase: the EAS production variables did not reach it."
    problems=1
  fi
  if grep -rqF 'EXPO_PUBLIC_E2E:"1"' apps/app/dist 2>/dev/null; then
    warn "The export has the end-to-end test seams switched on (EXPO_PUBLIC_E2E=1)."
    problems=1
  fi
  if (( problems == 0 )); then
    printf '  %s✓ the export looks like production%s\n' "$GREEN" "$RESET"
    deploy_ok=1
  fi
else
  say "Without a finished export there is nothing to check or upload."
fi
if (( deploy_ok == 1 )); then
  offer_run apps/app "3. Upload the checked export to production on EAS Hosting." eas deploy --prod
  note "The export is in apps/app/dist (git-ignored); you can delete it once it is deployed."
else
  warn "Not deploying."
  SKIPPED+=("deploy the web app (cd apps/app): export with eas env:exec production, check the export, then eas deploy --prod")
fi
printf '\n'
step "The deploy prints the production URL (for example https://pawpin.expo.app)."
while :; do
  ask WEB_ORIGIN "Web address of the deployed app (or empty if you have not deployed):" || true
  if [[ -z "${WEB_ORIGIN:-}" || "$WEB_ORIGIN" =~ ^https://[A-Za-z0-9.-]+$ ]]; then break; fi
  warn "Give only the origin, like https://pawpin.expo.app (no path, no trailing slash)."
done
write_env WEB_ORIGIN "${WEB_ORIGIN:-}"
if [[ -n "${WEB_ORIGIN:-}" ]]; then
  note "A custom domain, if you add one later, must be added in the next stage as well."
fi

# ── 17 ────────────────────────────────────────────────────────────────────
stage "Allow the web address to sign in"
if [[ -z "${WEB_ORIGIN:-}" ]]; then
  warn "No web address yet. Do this stage once the app is deployed: run this wizard again."
  SKIPPED+=("Supabase Authentication → URL Configuration: add the web origin(s) as Site URL and redirect URLs")
else
  say "Web sign-in with Apple sends people to Apple and back. Supabase only sends them back to"
  say "addresses on its redirect allowlist."
  open_url "$DASH/auth/url-configuration"
  step "Authentication → URL Configuration."
  step "Site URL:  $WEB_ORIGIN"
  step "Redirect URLs: add these two (and the same two for any custom domain):"
  show_block "$WEB_ORIGIN
$WEB_ORIGIN/**"
  step "Remove the default http://localhost:3000 entries if they are still there."
  warn "Web Apple sign-in uses PKCE: the sign-in must finish in the same browser, on the same"
  warn "origin, where it started. Do not start on one address and come back on another."
  pause "URL configuration saved? Press Enter."
fi

# ── 18 ────────────────────────────────────────────────────────────────────
stage "Invite the testers"
say "Only addresses in identity.pilot_allowlist can sign up. Enter the testers' emails."
note "A tester who uses Apple's 'Hide My Email' signs up with a relay address you cannot guess."
note "They try once and are refused; their relay address is then in identity.signup_rejections."
while :; do
  ask TESTER_EMAILS "Tester emails, separated by spaces or commas:" || true
  list="${TESTER_EMAILS:-}"
  list="${list//,/ }"
  list="${list//;/ }"
  tester_values=""
  count=0
  bad=0
  read -r -a parts <<<"$list" || true
  for ((n = 0; n < ${#parts[@]}; n++)); do
    e="$(printf '%s' "${parts[$n]}" | tr '[:upper:]' '[:lower:]')"
    if [[ "$e" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then
      tester_values+="${tester_values:+, }('$e')"
      count=$((count + 1))
    else
      warn "Not an email address, so left out: $e"; bad=1
    fi
  done
  if (( count > 0 && bad == 0 )); then break; fi
  if (( count == 0 && bad == 0 )); then
    note "No emails entered: skipping. You can add testers later in the SQL Editor."
    break
  fi
  warn "Fix the list and enter it again."
done
if (( count > 0 )); then
  ALLOWLIST_SQL="insert into identity.pilot_allowlist (email) values ${tester_values} on conflict do nothing;"
  open_url "$DASH/sql/new"
  step "Run this in the SQL Editor:"
  show_block "$ALLOWLIST_SQL"
  offer_copy "$ALLOWLIST_SQL"
  pause "Done? Press Enter."
else
  SKIPPED+=("add testers: insert into identity.pilot_allowlist (email) values ('tester@example.com');")
fi
say "To see addresses that were refused (for example Apple relay addresses):"
show_block "select * from identity.signup_rejections order by rejected_at desc;"
pause "Press Enter to continue."

# ── 19 ────────────────────────────────────────────────────────────────────
stage "iOS build and TestFlight"
say "The first build asks for your Apple login and creates the signing certificate and profile."
say "It takes a while and uses a build from your EAS plan. You can do this part later."
offer_run . "Build the production iOS app on EAS." pnpm build:ios
offer_run . "Send the latest build to TestFlight." pnpm submit:ios
printf '\n'
open_url "https://appstoreconnect.apple.com/apps"
step "App Store Connect → your app → TestFlight. When the build has finished processing:"
step "Add internal testers (members of your team), or an external group (the first build"
step "needs Beta App Review) and invite your testers' Apple ID emails."
pause "Press Enter to continue."

# ── 20 ────────────────────────────────────────────────────────────────────
stage "Pilot checks and what is left"
say "Do these by hand with a real tester account once the app is out:"
step "Web: open ${WEB_ORIGIN:-the hosted address} at phone and desktop width; sign in with an email code and with Apple."
step "iPhone (TestFlight): sign in with Apple (the native id-token path), add a pet, take photos."
step "Reload a pet's profile, and its photos and edit pages, on the hosted web app: a hard reload, a"
step "bookmark, and a link sent to someone else must each open the right screen. A 404 means the"
step "static export has no page for pet ids on EAS Hosting: see README 'Hosted web notes' for the fix."
step "A stranger sees 'This pilot is invite-only' and, if you set one, the support link."
step "Delete a pet and delete the account; the photos disappear."
printf '\n'
say "Owner follow-ups, also listed at the end:"
step "Install Maestro (it needs you to trust its Homebrew tap), then run: pnpm test:e2e:ios"
step "Give the web Apple button Apple's branded styling before a public launch (Apple's guidelines)."
SKIPPED+=("pilot check: on the hosted web app, hard-reload a pet's profile, photos and edit pages (/pets/<id>, /pets/<id>/photos, /pets/<id>/edit); if they 404, switch web.output to 'server' (README: Hosted web notes)")
SKIPPED+=("install Maestro (https://docs.maestro.dev/getting-started/installing-maestro; trusting its Homebrew tap is your call), then run pnpm test:e2e:ios before each TestFlight build")
SKIPPED+=("before a public launch: give the web Apple button Apple-branded styling (Human Interface Guidelines)")
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
